package net.minecraft.stats; import net.minecraft.item.*; import java.util.*; public class Achievement {public static final List<Achievement> ALL=new ArrayList<>();public final String statId,name;public final int displayColumn,displayRow;public final ItemStack theItemStack;public final Achievement parentAchievement;public Achievement(String id,String n,int x,int y,ItemStack i,Achievement p){statId=id;name=n;displayColumn=x;displayRow=y;theItemStack=i;parentAchievement=p;}public Achievement initIndependentStat(){return this;}public Achievement registerStat(){ALL.add(this);return this;}}
